BEGIN;

-- Les séquences doivent dépasser les id insérés explicitement par le catalogue de démonstration.
SELECT setval('manufacturers_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM manufacturers), 1));
SELECT setval('categories_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM categories), 1));
SELECT setval('parts_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM parts), 1));
SELECT setval('part_references_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM part_references), 1));
SELECT setval('supersessions_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM supersessions), 1));
SELECT setval('compatibilities_id_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM compatibilities), 1));

